insert into event_briefs (campaign_id, format, location, verticals, themes, personas, geography, cities, min_seniority, tiers, tier_mode, objective, outreach_lead, target_guests, acceptance_rate, approval_rate, sequence) values
  ('701Sb0000000001AAA', 'F1 · Executive hospitality', 'Las Vegas, NV', '{"Retail","Financial Services"}', '{"Apps & Agents","Software Factories"}', '{"CTO","CIO","SVP Engineering","VP Engineering","VP Platform Engineering","Head of AI"}', 'nationwide', '{}', 'vp', '{"Tier 1","Tier 2"}', 'prefer', 'balanced', 'ae', 10, 40, 75, '[{"day":0,"channel":"Email","sender":"AE","subject":"{first_name}, a seat for you at the Las Vegas Grand Prix","body":"Hi {first_name},\n\n{personal_line}\n\nVercel is hosting a small group of technology leaders at the Las Vegas Grand Prix on {date}: race-week hospitality, and an unhurried conversation about how teams are shipping AI apps and agents to production. We have ten seats, and I''d like one of them to be yours.\n\nShall I hold a seat for you?\n\n{sender_first_name}"},{"day":4,"channel":"LinkedIn","sender":"AE","subject":"","body":"Hi {first_name}, I sent you a note about Vercel''s suite at the Las Vegas Grand Prix on {date}. It''s a small group of technology leaders, and I think you''d enjoy the company. Happy to share details here if that''s easier."},{"day":9,"channel":"Email","sender":"AE","subject":"Re: {first_name}, a seat for you at the Las Vegas Grand Prix","body":"Hi {first_name},\n\nFollowing up on the Grand Prix. A few of the guests are working through how to get AI apps and agents from pilot to production safely, and I think the conversation would be worth your evening even before the race starts.\n\nIf the dates work, I''ll hold a seat for {account}.\n\n{sender_first_name}"},{"day":14,"channel":"Email","sender":"AE","subject":"Last seats for the Las Vegas Grand Prix","body":"Hi {first_name},\n\nWe''re confirming the last seats in Vercel''s Las Vegas Grand Prix suite this week. If you''d like to join us on {date}, reply here and I''ll take care of the details.\n\n{sender_first_name}"}]'::jsonb),
  ('701Sb0000000009AAA', 'Retail · Partner breakfast', 'New York, NY', '{"Retail"}', '{"Apps & Agents"}', '{"CTO","CIO","VP Digital Commerce","VP Engineering"}', 'city', '{"New York, NY"}', 'director', '{"Tier 1","Tier 2","Tier 3"}', 'prefer', 'net_new', 'bdr', 20, 35, 75, '[{"day":0,"channel":"Email","sender":"BDR","subject":"AI & Avocados: retail leaders breakfast at NRF","body":"Hi {first_name},\n\n{personal_line}\n\nVercel is hosting a breakfast for retail technology and commerce leaders during NRF on {date} in New York, with Stripe, Contentful and others. The topic is agentic commerce: what changes when AI assistants start shopping and checking out for customers.\n\nWould you like to join us?\n\n{sender_first_name}"},{"day":3,"channel":"LinkedIn","sender":"BDR","subject":"","body":"Hi {first_name}, are you at NRF this year? We''re hosting a small retail leaders breakfast on {date} about agentic commerce, and I thought of {account}."},{"day":7,"channel":"Email","sender":"BDR","subject":"Re: AI & Avocados: retail leaders breakfast at NRF","body":"Hi {first_name},\n\nA quick follow-up on the NRF breakfast on {date}. It''s an hour, close to the Javits Center, and a good room for comparing notes on AI shopping assistants and checkout.\n\nShall I save you a spot?\n\n{sender_first_name}"},{"day":10,"channel":"Email","sender":"AE","subject":"Joining us at NRF?","body":"Hi {first_name},\n\nI look after Vercel''s relationship with {account}. We have a few places left at our NRF breakfast on {date}, and I''d be glad to meet you there.\n\n{sender_first_name}"}]'::jsonb),
  ('701Sb0000000010AAA', 'Horizontal ABM · Executive dinner', 'San Francisco, CA', '{"Cross-industry"}', '{"Apps & Agents","Software Factories"}', '{"CIO","VP Platform Engineering","Head of AI","Head of Security"}', 'city', '{"San Francisco, CA"}', 'vp', '{"Tier 1","Tier 2"}', 'prefer', 'balanced', 'mixed', 12, 35, 75, '[{"day":0,"channel":"Email","sender":"AE","subject":"When anyone can build, who governs what ships?","body":"Hi {first_name},\n\n{personal_line}\n\nVercel''s engineering leaders are hosting a small dinner in San Francisco on {date} for leaders working through the same question: when more people can build apps and agents with AI, how do you govern what reaches production? It''s off the record, with a dozen peers.\n\nWould you like to join us?\n\n{sender_first_name}"},{"day":5,"channel":"Email","sender":"BDR","subject":"Re: When anyone can build, who governs what ships?","body":"Hi {first_name},\n\nFollowing up on the dinner on {date}. Guests are bringing real examples of AI-built apps they''ve had to secure and roll out, so the conversation is practical rather than a pitch.\n\nShall I hold a seat for you?\n\n{sender_first_name}"},{"day":10,"channel":"LinkedIn","sender":"AE","subject":"","body":"Hi {first_name}, I''d love to have you at our governance dinner in San Francisco on {date}. A small group, and I think your view from {account} would add a lot."}]'::jsonb);
