  ('Akshay Kothari', 'Co-Founder', 'Notion', 3730, 'https://www.linkedin.com/in/akothari', 'customer_leader', 'Via existing customer', 'Sumble people search (CXO)', '[{"title":"Co-Founder","start_date":"2018-08","location":"San Francisco Bay Area","employer":{"organization_id":3730,"name":"Notion","slug":"notion-labs","linkedin_url":"https://www.linkedin.com/company/notionhq","sumble_url":"https://sumble.com/l/org/EOqpf5B19rxQ"}},{"title":"VP Product, Head of LinkedIn India","start_date":"2016-01","end_date":"2018-08","location":"Bengaluru Area, India","description":"Country Manager for LinkedIn''s second biggest market, with 50+ million members and 1000+ employees. Responsible for international R&D teams (China, Japan, Germany, India)","employer":{"organization_id":61349,"name":"LinkedIn","slug":"linkedin","linkedin_url":"https://www.linkedin.com/company/linkedin","sumble_url":"https://sumble.com/l/org/8RVScY81ano9"}},{"title":"Product Lead","start_date":"2013-04","end_date":"2015-12","location":"Mountain view, CA","description":"Product lead for major content initiatives at Linkedin, including Pulse, Publishing Platform and Influencer program","employer":{"organization_id":61349,"name":"LinkedIn","slug":"linkedin","linkedin_url":"https://www.linkedin.com/company/linkedin","sumble_url":"https://sumble.com/l/org/8RVScY81ano9"}},{"title":"Co-Founder/CEO","start_date":"2010-05","end_date":"2013-04","location":"San Francisco, CA","description":"Pulse was an award-winning application for iPhone, iPad, Android and the web. It gave users the opportunity to access their favorite content—from traditional news sources to blogs to social networks—all in one beautiful interface. Pulse had been named to Apple''s App Store Hall of Fame, chosen as an Android Editor''s Choice app, selected as one of TIME''s top 50 iPhone apps of 2011, and honored with the Apple Design Award. Pulse was acquired by LinkedIn in 2013 for $90 million.","employer":{"name":"LinkedIn Pulse","linkedin_url":"https://www.linkedin.com/company/pulse-news"}},{"title":"Analyst","start_date":"2007-06","end_date":"2008-05","location":"Los Altos, CA","employer":{"name":"Sdl Ventures","linkedin_url":"https://www.linkedin.com/company/sdl-ventures"}},{"title":"Intern","start_date":"2006-06","end_date":"2006-08","location":"Bangalore, India","employer":{"organization_id":71,"name":"Infosys Technologies","slug":"infosys","linkedin_url":"https://www.linkedin.com/company/infosys","sumble_url":"https://sumble.com/l/org/H8nxoQsfU0Q"}},{"title":"Intern","start_date":"2005-01","end_date":"2005-12","location":"Coopersburg, PA","employer":{"organization_id":3640,"name":"Lutron Electronics","slug":"lutron-electronics","linkedin_url":"https://www.linkedin.com/company/lutron-electronics","sumble_url":"https://sumble.com/l/org/ysJUHCj8ANz"}}]'::jsonb),
  ('Eric Glyman', 'Co-Founder & CEO', 'Ramp', 6943, 'https://www.linkedin.com/in/eglyman', 'customer_leader', 'Via existing customer', 'Sumble people search (CXO); Ramp is a Vercel customer story', '[{"title":"Co-Founder, CEO","start_date":"2019-03","description":"Ramp is building the next generation of finance tools – from corporate cards and expense management, to bill payments and accounting integrations – designed to save businesses time and money with every click. Over 30,000 companies are spending an average of 5% less and closing their books 8x faster by switching to Ramp''s finance automation platform. Founded in 2019, Ramp powers the fastest-growing corporate card and bill payment software in America. Recently named Fast Company’s 2023 Most Innovative Company in North America, investors include Founders Fund, Sequoia Capital, Coatue Management, D1 Capital Partners, Thrive Capital, Sands Capital, Redpoint Ventures, Iconiq Growth, Altimeter, Stripe, Goldman Sachs, Citi, Lux Capital, Vista Public Strategies, Spark Capital, Definition Capital, General Catalyst, 137 Ventures, Neo, Soma Capital, and Declaration Partners, and more.","employer":{"organization_id":6943,"name":"Ramp","slug":"ramp-2","linkedin_url":"https://www.linkedin.com/company/ramp","sumble_url":"https://sumble.com/l/org/bQI6XO60ECdd"}},{"title":"Sr. Director, Paribus @ US Card / CEO, Paribus","start_date":"2016-10","end_date":"2019-02","location":"New York City Metropolitan Area","employer":{"organization_id":26,"name":"Capital One","slug":"capital-one","linkedin_url":"https://www.linkedin.com/company/capital-one","sumble_url":"https://sumble.com/l/org/57TXQzxsaa"}},{"title":"Co-Founder","start_date":"2014-01","end_date":"2019-02","location":"Brooklyn, NY","description":"Join Paribus today","employer":{"name":"Paribus Co.","linkedin_url":"https://www.linkedin.com/company/paribus-co-"}},{"title":"Financial Analyst","start_date":"2012-07","end_date":"2014-09","location":"New York, NY","description